CALL `__rotation_add_col_if_missing`('accounting_db_3', 'account_31', 'effective_hard_timeout_secs', 'INT DEFAULT NULL COMMENT ''策略覆盖：本 instance 专用 hard timeout，紧急运维通道（§11.X）''');
