CALL `__rotation_add_col_if_missing`('accounting_db_6', 'account_62', 'lifecycle_phase', 'TINYINT NOT NULL DEFAULT 0 COMMENT ''0=legacy 1=active 2=draining 3=frozen 4=archived 5=provisioned 9=quarantined''');
CALL `__rotation_add_col_if_missing`('accounting_db_6', 'account_62', 'draining_started_at', 'DATETIME DEFAULT NULL COMMENT ''进入 draining 的时刻''');
CALL `__rotation_add_col_if_missing`('accounting_db_6', 'account_62', 'frozen_at', 'DATETIME DEFAULT NULL COMMENT ''进入 frozen 的时刻''');
CALL `__rotation_add_col_if_missing`('accounting_db_6', 'account_62', 'archived_at', 'DATETIME DEFAULT NULL COMMENT ''进入 archived 的时刻''');
CALL `__rotation_add_col_if_missing`('accounting_db_6', 'account_62', 'policy_version_at_birth', 'BIGINT DEFAULT NULL COMMENT ''出生时锁定的 policy_version；后续策略变更不影响本 instance（E-28/E-29）''');
CALL `__rotation_add_col_if_missing`('accounting_db_6', 'account_62', 'effective_hard_timeout_secs', 'INT DEFAULT NULL COMMENT ''策略覆盖：本 instance 专用 hard timeout，紧急运维通道（§11.X）''');
CALL `__rotation_add_col_if_missing`('accounting_db_6', 'account_62', 'override_reason', 'VARCHAR(255) DEFAULT NULL COMMENT ''override 原因（运维填写）''');
CALL `__rotation_add_col_if_missing`('accounting_db_6', 'account_62', 'override_by', 'VARCHAR(64) DEFAULT NULL COMMENT ''override 操作人''');
CALL `__rotation_add_col_if_missing`('accounting_db_6', 'account_62', 'override_at', 'DATETIME DEFAULT NULL COMMENT ''override 时刻''');
CALL `__rotation_add_idx_if_missing`('accounting_db_6', 'account_62', 'idx_logical_phase', 'KEY `idx_logical_phase` (`logical_account_id`, `lifecycle_phase`)');
CALL `__rotation_add_idx_if_missing`('accounting_db_6', 'account_62', 'idx_phase_period_end', 'KEY `idx_phase_period_end` (`lifecycle_phase`, `period_end`)');

